unit WithScopeDemo;

interface

type
  TPoint = record
    X, Y : Integer;
  end;

  TBounds = record
    Min, Max : TPoint;
  end;

function RangeWidth(const B : TBounds; X : Integer) : Integer;

implementation

function RangeWidth(const B : TBounds; X : Integer) : Integer;
begin
  // The X passed by the caller is meant to be a default for
  // Min.X. But inside the with-block, `X` resolves to Min.X
  // (the record field) NOT the parameter -- because the with
  // scope shadows it. Result: the function ignores its X
  // argument and reads whatever Min.X happens to be.
  with B.Min do
  begin
    Result := B.Max.X - X;
  end;
end;

end.
